import {createLines,lineModel,changeLines,lineReference,lineWords,linePaperCopy,lineExample} from './poem-lines-core.mjs';
import {poemCases,lineCopy as copy} from './poem-lines-content.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null,retireBinding=()=>{},stopBinding=()=>{};
export function resetPoemLines(){retireBinding();stopBinding();stopBinding=()=>{};visit=null;}
function current(book,owner){if(!visit||visit.notebook!==book||visit.explorerId!==owner){resetPoemLines();visit={notebook:book,explorerId:owner,id:null,work:new Map(),selected:new Map(),view:'chooser',reference:'a',frame:0,caller:'editor'};}return visit;}
const button=(action,label,disabled=false,extra='')=>`<button type="button" data-pl-action="${action}"${disabled?' disabled':''} ${extra}>${esc(label)}</button>`;
const read=text=>`<p>${esc(text)}</p>`;
function catalog(id){return `<div class="pl-catalog">${poemCases.map(p=>`<button type="button" data-pl-start="${p.id}"${p.id===id?' aria-current="true"':''}><span>${esc(p.title)}</span><small>${esc(p.text)}</small></button>`).join('')}</div>`;}
const spokenLine=n=>['one','two','three','four','five','six','seven','eight','nine','ten'][n-1]||n;
function paper(model,kind,selected=0,boundary=0){return `<div class="pl-paper" data-pl-paper="${kind}">${model.lines.map((line,i)=>`<div class="pl-line" data-pl-line="${i+1}"${line.end===boundary?' data-pl-highlight-boundary="true"':''} role="group" aria-label="Line ${spokenLine(i+1)}"><span class="pl-tab" aria-hidden="true">Line ${i+1}</span><div class="pl-line-words">${line.words.map(w=>`<span class="pl-word-unit">${kind==='own'&&selected?`<button type="button" class="pl-word" data-pl-word="${w.position}" aria-label="${esc(`Word ${w.position}: ${w.text}`)}" aria-pressed="${w.position===selected}"><span data-pl-token>${esc(w.text)}</span></button>`:`<span class="pl-word pl-fixed" data-pl-token>${esc(w.text)}</span>`}${w.pause?`<span class="pl-cue" data-pl-cue>${w.pause==='long'?'longer pause':'pause'}</span>`:''}</span>`).join(' ')}</div></div>`).join('')}</div>`;}
function speech(id,example=false,compare=false){return `<div class="pl-reading">${hearButton(example?lineExampleText:lineWords(id),example?'Read example words':compare?'Read the words — own arrangement':'Read the words')}${read(copy.speechHint)}</div>`;}
function exportButton(){return `<div class="pl-export">${button('export','Take a paper copy')}${read(copy.downloadHint)}</div>`;}
function example(v){const ex=lineExample(v.frame);return `<div data-pl-view="example" data-pl-frame="${v.frame}"><h2 id="pl-heading" tabindex="-1">Show a separate example</h2>${read('These are separate example words. Your arrangement stays as you left it.')}<div class="pl-example-papers">${ex.layouts.map(layout=>`<section><h3>${esc(layout.label)}</h3>${paper(layout,'example',0,v.frame===1?2:0)}</section>`).join('')}</div><p class="pl-caption" role="status" data-pl-caption>Picture ${v.frame+1} of 5. ${esc(ex.caption)}</p>${speech(v.id,true)}<nav class="pl-actions" aria-label="Example pictures">${button('previous','Previous',v.frame===0)}${button('next','Next',v.frame===4)}${button('back',v.caller==='compare'?'Back to comparison':'Back to my poem')}</nav></div>`;}
function compare(v){const own=lineModel(v.id,v.work.get(v.id)),ref=lineModel(v.id,lineReference(v.id,v.reference)),p=poemCases.find(p=>p.id===v.id);return `<div data-pl-view="compare"><h2 id="pl-heading" tabindex="-1">Compare layouts: ${esc(own.title)}</h2>${read(copy.compareSubtitle)}<div class="pl-reference-choices" role="group" aria-label="Example layout">${['a','b'].map(r=>`<button type="button" data-pl-reference="${r}" aria-pressed="${v.reference===r}">Show layout ${r.toUpperCase()}</button>`).join('')}</div><div class="pl-comparison"><section><h3>Own arrangement</h3>${paper(own,'own')}</section><section><h3>Example layout ${v.reference.toUpperCase()}</h3>${paper(ref,'reference')}</section></div>${read(copy.wrap)}<p class="pl-compare-note" data-pl-compare-note>${esc(p.note)}</p>${speech(v.id,false,true)}<div class="pl-actions">${button('back','Back to my poem')}${button('example','Show a separate example')}</div>${exportButton()}</div>`;}
function editor(v){const m=lineModel(v.id,v.work.get(v.id)),selected=v.selected.get(v.id),last=selected===m.tokens.length,pause=m.pauses[selected]??'',hasBreak=m.breaks.includes(selected);return `<div data-pl-view="editor" data-pl-poem="${v.id}"><h2 id="pl-heading" tabindex="-1">${esc(m.title)}</h2>${read(copy.request)}<div class="pl-editor"><div class="pl-material">${paper(m,'own',selected)}${read(copy.wrap)}</div><section class="pl-toolbar" aria-label="Change this arrangement"><label for="pl-word-select">Word to change</label><select id="pl-word-select" data-pl-word-select>${m.tokens.map((token,i)=>`<option value="${i+1}"${selected===i+1?' selected':''}>${i+1}: ${esc(token)}</option>`).join('')}</select>${button('break',hasBreak?'Join next line':'End line here',last)}<div class="pl-pause-choices" role="group" aria-label="Pause after selected word">${[['','No pause'],['brief','Brief pause'],['long','Longer pause']].map(([kind,label])=>button('pause',label,last,`data-pl-pause="${kind}" aria-pressed="${kind===pause}"`)).join('')}</div>${last?read(copy.lastWord):''}${read(copy.cueKey)}${button('undo','Undo last change',!m.canUndo)}${!m.canUndo?read(copy.noUndo):''}${button('reset','Start this layout again')}${read('Returns to the starting line endings and clears pause notes for this poem.')}</section></div>${speech(v.id)}<div class="pl-actions">${button('compare','Compare layouts')}${button('example','Show a separate example')}</div>${exportButton()}<details><summary>Choose another poem</summary>${catalog(v.id)}</details><details><summary>Talk together</summary><ul>${copy.invitations.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></details></div>`;}
export function poemLinesEntry(){return '<a href="#loft/lines">The Line Table: reshape a poem</a>';}
export function poemLinesPage(book,owner){const v=current(book,owner);return `<section class="pl-page" data-pl-root><header class="pl-header"><nav aria-label="Nearby places"><a href="#loft">Story Loft</a><a href="#studio/rhythm">Rhythm Studio</a></nav><h1>${esc(copy.title)}</h1>${read(copy.rhythmContrast)}</header><div class="pl-workmat">${v.view==='example'?example(v):v.view==='compare'?compare(v):v.view==='editor'?editor(v):`<div data-pl-view="chooser"><h2 id="pl-heading" tabindex="-1">${esc(copy.chooser)}</h2>${read(copy.intro)}${catalog(null)}</div>`}<p class="pl-visit">${esc(copy.visit)}</p><details><summary>For grown-ups</summary>${read(copy.grownUp)}</details></div></section>`;}
function bindingGuard(root,valid,stop){
 const controls=[root,...root.querySelectorAll('button,input,select,a,summary,details')].filter(n=>!n.closest?.('.speech-controls,drawn-howto')),chains=new Map(),retired=new WeakSet();let disconnected=false;
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};for(const n of controls)chains.set(n,chain(n));
 const audit=records=>{for(const r of records){if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid()||retired.has(root)){stop();disconnect();}});
 const disconnect=()=>{if(!disconnected){disconnected=true;observer.disconnect();}};
 observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return {disconnect,accepts(node){audit(observer.takeRecords());if(disconnected||!valid()||!root.isConnected||!root.contains(node)||node.disabled||retired.has(node))return false;const old=chains.get(node),now=chain(node);if(!old||old.length!==now.length||!old.every((n,i)=>n===now[i]))return false;for(let n=node;n?.nodeType===1;n=n.parentElement){const css=getComputedStyle(n);if(n.hidden||n.inert||n.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(n.tagName==='DETAILS'&&!n.open&&n!==node&&!n.querySelector(':scope>summary')?.contains(node))return false;}return node.getClientRects().length>0;}};
}
export function bindPoemLines(book,ctx){
 retireBinding();const root=document.querySelector('[data-pl-root]');if(!root||!visit)return;
 const v=visit,owner=typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,id=v.id,material=v.work.get(id),bytes=JSON.stringify(material),selected=v.selected.get(id),view=v.view,frame=v.frame,reference=v.reference,parent=root.parentNode;
 const live=()=>root.isConnected&&root.parentNode===parent&&document.querySelector('[data-pl-root]')===root&&location.hash==='#loft/lines'&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook??book)===book&&(!ctx.isActive||ctx.isActive())&&(typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId)===owner&&visit===v&&v.notebook===book&&v.explorerId===owner&&v.id===id&&v.work.get(id)===material&&JSON.stringify(material)===bytes&&v.selected.get(id)===selected&&v.view===view&&v.frame===frame&&v.reference===reference;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();},guard=bindingGuard(root,live,stop);retireBinding=guard.disconnect;stopBinding=stop;
 for(const control of root.querySelectorAll('button,input,select,a,summary,details')){if(control.closest('.speech-controls,drawn-howto'))continue;for(const type of ['click','input','change','keydown'])control.addEventListener(type,event=>{if(!guard.accepts(control)){event.preventDefault();event.stopImmediatePropagation();}},{capture:true});}
 const redraw=(selector='#pl-heading')=>{guard.disconnect();ctx.render();let target=document.querySelector(selector);if(!target||target.disabled||!target.getClientRects().length)selector='[data-pl-word-select]';target=document.querySelector(selector);if(!target||target.disabled||!target.getClientRects().length)selector='#pl-heading';if(ctx.focus)ctx.focus(selector);else document.querySelector(selector)?.focus();};
 root.querySelectorAll('[data-pl-start]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b)||!poemCases.some(p=>p.id===b.dataset.plStart))return;stop();v.id=b.dataset.plStart;if(!v.work.has(v.id)){v.work.set(v.id,createLines(v.id));v.selected.set(v.id,1);}v.view='editor';redraw();}));
 const selectWord=(position,selector)=>{if(view!=='editor'||!Number.isInteger(position)||position<1||position>lineModel(id,material).tokens.length)return;v.selected.set(id,position);redraw(selector);};
 root.querySelectorAll('[data-pl-word]').forEach(b=>b.addEventListener('click',()=>{if(guard.accepts(b))selectWord(Number(b.dataset.plWord),`[data-pl-word="${b.dataset.plWord}"]`);}));
 root.querySelector('[data-pl-word-select]')?.addEventListener('change',event=>{if(guard.accepts(event.currentTarget))selectWord(Number(event.currentTarget.value),'[data-pl-word-select]');});
 root.querySelectorAll('[data-pl-reference]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b)||view!=='compare'||!['a','b'].includes(b.dataset.plReference)||reference===b.dataset.plReference)return;stop();v.reference=b.dataset.plReference;redraw(`[data-pl-reference="${v.reference}"]`);}));
 root.querySelectorAll('[data-pl-action]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b))return;const action=b.dataset.plAction;
 if(action==='example'){stop();v.caller=view;v.view='example';v.frame=0;redraw();return;}
 if(action==='back'){stop();if(view==='example'){v.view=v.caller;redraw('[data-pl-action="example"]');}else if(view==='compare'){v.view='editor';redraw('[data-pl-action="compare"]');}return;}
 if(view==='example'){if(!['previous','next'].includes(action))return;const next=frame+(action==='next'?1:-1);if(!lineExample(next))return;stop();v.frame=next;redraw(`[data-pl-action="${next===4?'previous':next===0?'next':action}"]`);return;}
 if(!material)return;
 if(action==='compare'&&view==='editor'){stop();v.view='compare';v.reference='a';redraw();return;}
 if(action==='export'&&['editor','compare'].includes(view)){const text=linePaperCopy(id,material);if(typeof text!=='string'||!guard.accepts(b))return;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`line-table-${id}.txt`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(view!=='editor'||!['break','pause','undo','reset'].includes(action))return;
 const next=changeLines(id,material,action,action==='break'?selected:action==='pause'?{position:selected,kind:b.dataset.plPause||null}:undefined);if(!next||next===material)return;stop();v.work.set(id,next);redraw(action==='pause'?`[data-pl-action="pause"][data-pl-pause="${b.dataset.plPause}"]`:`[data-pl-action="${action}"]`);
 }));
}
